def quicksort(arr):
 if len(arr) <= 1:
 return arr
 pivot = arr[len(arr) // 2]
 less_than_pivot = [x for x in arr if x < pivot]
 equal_to_pivot = [x for x in arr if x == pivot]
 greater_than_pivot = [x for x in arr if x > pivot]
 return quicksort(less_than_pivot) + equal_to_pivot + quicksort(greater_than_pivot)

def matching_paren(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if len(stack) == 0:
                return False 
            stack.pop()

    if len(stack) == 0:
        return True
    else:
        return False

