def permutations(string):
  # base case
  if len(string) <= 1:
    return set([string])

  # recursive case
  else:
    perms = permutations(string[1:])
    char = string[0]
    result = set()
    for perm in perms:
      for i in range(len(perm)+1):
        result.add(perm[:i] + char + perm[i:])
    return result

