def find_permutations(s): 
	res = [] 
	find_permutations_recur(s, "", res) 
	return res 

def find_permutations_recur(str, prefix, res): 
	n = len(str)
	if n == 0:
		res.append(prefix) 
		return

	for i in range(n):
		remaining = str[0:i] + str[i+1:] 
		find_permutations_recur(remaining, prefix + str[i], res)

