def binary_search(numbers, n):
   start = 0
   end = len(numbers) - 1

   while start <= end:
      mid = (start + end) // 2
      if numbers[mid] == n:
         return mid
      elif numbers[mid] < n:
         start = mid + 1
      else:
         end = mid - 1
   return -1

