  for key, value in d.items():
    if isinstance(value, dict):
      value = flatten(value) 
      for sub_key, sub_value in value.items(): 
        flatten_d[key + '.' + sub_key] = sub_value 
    else: 
      flatten_d[key] = value 
  return flatten_d

