def is_permutation(s1, s2):
    if len(s1) != len(s2):
        return False

    c1 = [0] * 256
    c2 = [0] * 256

    for i in range(len(s1)):
        c1[ord(s1[i])] += 1
        c2[ord(s2[i])] += 1

    if c1 == c2:
        return True
    else:
        return False

