n = 20

def calculate_sum_of_primes(n):
    result = 0
    if n >= 2:
        primes = [2]
        for i in range(3, n + 1, 2):
            for j in primes:
                if i % j == 0:
                    break
            else:
                primes.append(i)
        result = sum(primes)
    return result

