def gcd(a, b):
   while a != 0:
       a, b = b % a, a
   return b

def reduce_by_gcd(arr):
    gcd_val = arr[0]
    for i in range(len(arr)):
        gcd_val = gcd(gcd_val, arr[i])
    return [a // gcd_val for a in arr]

reduced_arr = reduce_by_gcd([30, 20, 45])
