def caesar_cipher_encrypt(plain_text, shift): 
    cipher_text = "" 

    for char in plain_text: 
        if char == ' ': 
            cipher_text += char 
        elif  char.isupper(): 
            cipher_text += chr((ord(char) + shift - 65) % 26 + 65) 
        else: 
            cipher_text += chr((ord(char) + shift - 97) % 26 + 97) 

    return cipher_text

