def is_sorted(array):
    n = len(array)
    # Array of length 0 or 1 is considered sorted
    if n == 0 or n == 1:
        return True
    for i in range(n-1):
        # Without the equals it will return false even when the array was sorted
        if array[i] > array[i+1]:
            return False
    return True

