# function to check if  
# given number is perfect square 
def isPerfectSquare(n): 

    if n < 0: 
        return False

    # Base case 
    if n == 1: 
        return True

    i = 1
    x = n // 2

    while x >= i: 
        if (x == i) and (n % x == 0): 
            return True
        x -= 1
    return False

