def extract_random_subset(li, size=100): 
    subset = [] 
    while len(subset) < size: 
        rand_ele = random.choice(li)
        if rand_ele not in subset: 
            subset.append(rand_ele) 
    return subset

def find_last_occurrence(A, x):
    (left, right) = (0, len(A) - 1)
    result = -1
    while left <= right:
        mid = (left + right) // 2
        if x == A[mid]:
            result = mid
            left = mid + 1
        elif x < A[mid]:
            right = mid - 1
        else:
            left = mid + 1
    return result

