class Triangle:
    def __init__(self, side1, side2, side3):
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3

    def get_perimeter(self):
        return self.side1 + self.side2 + self.side3

    def get_area(self):
        s = self.get_perimeter() / 2
        return (s * (s-self.side1) * (s-self.side2) * (s-self.side3)) ** 0.5

