def find_deepest_node(root):
    if root is None: 
        return 
    queue = [] 
    queue.append(root) 

    deepest_node = None
    while queue:
        node = queue.pop(0)
        deepest_node = node 

        if node.left: 
            queue.append(node.left)
        if node.right: 
            queue.append(node.right)
    return deepest_node

