def nth_prime(n):
  prime_numbers = [2]
  num = 3
  while len(prime_numbers) < n:
    is_prime = True
    for i in range(2, int(num ** 0.5)+1):
      if num % i == 0:
        is_prime = False
        break
    if is_prime:
      prime_numbers.append(num)
    num += 1
  return prime_numbers[-1]

print(nth_prime(10))

def vowel_percentage(text):
    vowels = "aeiouAEIOU"
    num_vowels = 0
    for letter in text:
